schema:
{
     "$schema": "https://json-schema.org/draft/2020-12/schema",
     "type": "object",
     "properties": {
      "command": {
       "type": "string",
       "description": "The command to execute"
      },
      "timeout": {
       "minimum": -9007199254740991,
       "exclusiveMinimum": 0,
       "type": "integer",
       "maximum": 9007199254740991,
       "description": "Optional timeout in milliseconds"
      },
      "workdir": {
       "type": "string",
       "description": "The working directory to run the command in. Defaults to the current directory. Use this instead of 'cd' commands."
      }
     },
     "required": [
      "command"
     ]
    }

{
     "$schema": "https://json-schema.org/draft/2020-12/schema",
     "type": "object",
     "properties": {
      "filePath": {
       "type": "string",
       "description": "The absolute path to the file to modify"
      },
      "oldString": {
       "type": "string",
       "description": "The text to replace"
      },
      "newString": {
       "type": "string",
       "description": "The text to replace it with (must be different from oldString)"
      },
      "replaceAll": {
       "type": "boolean",
       "description": "Replace all occurrences of oldString (default false)"
      }
     },
     "required": [
      "filePath",
      "oldString",
      "newString"
     ]
    }

{
     "$schema": "https://json-schema.org/draft/2020-12/schema",
     "type": "object",
     "properties": {
      "pattern": {
       "type": "string",
       "description": "The glob pattern to match files against"
      },
      "path": {
       "type": "string",
       "description": "The directory to search in. If not specified, the current working directory will be used. IMPORTANT: Omit this field to use the default directory. DO NOT enter \"undefined\" or \"null\" - simply omit it for the default behavior. Must be a valid directory path if provided."
      }
     },
     "required": [
      "pattern"
     ]
    }

{
     "$schema": "https://json-schema.org/draft/2020-12/schema",
     "type": "object",
     "properties": {
      "pattern": {
       "type": "string",
       "description": "The regex pattern to search for in file contents"
      },
      "path": {
       "type": "string",
       "description": "The directory to search in. Defaults to the current working directory."
      },
      "include": {
       "type": "string",
       "description": "File pattern to include in the search (e.g. \"*.js\", \"*.{ts,tsx}\")"
      }
     },
     "required": [
      "pattern"
     ]
    }

{
     "type": "object",
     "properties": {
      "symbol": {
       "type": "string",
       "description": "The function name whose callers you want (exact match, no qualification \u2014 pass 'Login' not 'User.Login'). Returns files that contain a call to this name."
      },
      "repo": {
       "type": "string",
       "description": "https:// or http:// git URL or local directory path. Required when no default index was configured at startup."
      },
      "output": {
       "type": "string",
       "description": "Output format: 'markdown' (default) or 'json' (structured response with symbol/files \u2014 see CallersResponse)."
      }
     },
     "required": [
      "symbol"
     ],
     "additionalProperties": false
    }

{
     "type": "object",
     "properties": {
      "symbol": {
       "type": "string",
       "description": "The symbol name to locate (function or class name as written in source \u2014 exact match; no fuzzy matching, no qualification)."
      },
      "repo": {
       "type": "string",
       "description": "https:// or http:// git URL or local directory path. Required when no default index was configured at startup."
      },
      "output": {
       "type": "string",
       "description": "Output format: 'markdown' (default) or 'json' (structured response with symbol/definitions \u2014 see DefinitionResponse)."
      }
     },
     "required": [
      "symbol"
     ],
     "additionalProperties": false
    }

{
     "type": "object",
     "properties": {
      "file_path": {
       "type": "string",
       "description": "Path to the file as stored in the index (use file_path from a search result)."
      },
      "line": {
       "type": "integer",
       "description": "Line number (1-indexed)."
      },
      "repo": {
       "type": "string",
       "description": "https:// or http:// git URL or local directory path. Required when no default index was configured at startup."
      },
      "top_k": {
       "type": "integer",
       "description": "Number of similar chunks to return."
      },
      "max_tokens": {
       "type": "integer",
       "description": "Optional approximate token budget for the returned results (a soft ceiling on response size, complementary to top_k). When >0, results are filled top-down and the tail is dropped once the cumulative estimated token cost would exceed this \u2014 the top hit is always kept. Approximate: ken ships no BPE tokenizer, so this is a heuristic estimate, not an exact token count."
      },
      "output": {
       "type": "string",
       "description": "Output format: 'markdown' (default) or 'json' (structured response with anchor/results \u2014 see FindRelatedResponse)."
      }
     },
     "required": [
      "file_path",
      "line"
     ],
     "additionalProperties": false
    }

{
     "type": "object",
     "properties": {
      "path": {
       "type": "string",
       "description": "File path (relative to repo root) or directory path. A file returns just that file's outline; a directory returns outlines for every indexed file under it."
      },
      "repo": {
       "type": "string",
       "description": "https:// or http:// git URL or local directory path. Required when no default index was configured at startup."
      },
      "output": {
       "type": "string",
       "description": "Output format: 'markdown' (default) or 'json' (structured response with path/entries \u2014 see OutlineResponse)."
      },
      "offset": {
       "type": "integer",
       "description": "Directory paths only: skip this many files before listing (for paging past a truncated result). Default 0."
      },
      "limit": {
       "type": "integer",
       "description": "Directory paths only: max files to outline in one call (default and hard cap 500). Narrow with 'path' or page with 'offset' when truncated."
      }
     },
     "required": [
      "path"
     ],
     "additionalProperties": false
    }

{
     "type": "object",
     "properties": {
      "n": {
       "type": "integer",
       "description": "Number of recent commits to include (default 10, max 100)."
      },
      "repo": {
       "type": "string",
       "description": "Local directory path containing a git working tree. Required when no default index was configured at startup. Pass 1 of this tool does NOT support https:// URLs \u2014 for those, clone manually first."
      },
      "path": {
       "type": "string",
       "description": "Optional path prefix to filter the file list. Commits with no matching file changes are skipped from the output. E.g. 'src/api' returns only commits that touched something under src/api/."
      },
      "output": {
       "type": "string",
       "description": "Output format: 'markdown' (default) or 'json' (structured response with considered/commits \u2014 see RecentlyChangedResponse)."
      }
     },
     "additionalProperties": false
    }

{
     "type": "object",
     "properties": {
      "symbol": {
       "type": "string",
       "description": "The name to find references for (function, class, or any identifier \u2014 exact match)."
      },
      "repo": {
       "type": "string",
       "description": "https:// or http:// git URL or local directory path. Required when no default index was configured at startup."
      },
      "output": {
       "type": "string",
       "description": "Output format: 'markdown' (default) or 'json' (structured response with symbol/references/totals \u2014 see ReferencesResponse)."
      }
     },
     "required": [
      "symbol"
     ],
     "additionalProperties": false
    }

{
     "type": "object",
     "properties": {
      "repo": {
       "type": "string",
       "description": "Optional repo to also report live index state for. If set, the response includes file count, chunk count, mode, chunker, and structural-index symbol counts for that repo (resolved via the same cache the search tools use). If omitted, machine-level state only."
      },
      "verbose": {
       "type": "boolean",
       "description": "Include per-language extractor coverage + per-call-type counts in the response."
      },
      "output": {
       "type": "string",
       "description": "Optional output format: 'markdown' (default; human-readable) or 'json' (machine-parsable). Agents that want to programmatically inspect status should pass 'json'."
      }
     },
     "additionalProperties": false
    }

{
     "type": "object",
     "properties": {
      "path": {
       "type": "string",
       "description": "Optional path prefix (relative to repo root) to filter the symbol list. Empty/omitted returns every top-level symbol in the repo."
      },
      "repo": {
       "type": "string",
       "description": "https:// or http:// git URL or local directory path. Required when no default index was configured at startup."
      },
      "output": {
       "type": "string",
       "description": "Output format: 'markdown' (default) or 'json' (structured response with path_prefix/symbols \u2014 see SymbolsResponse)."
      },
      "offset": {
       "type": "integer",
       "description": "Skip this many symbols before listing (for paging past a truncated result). Default 0."
      },
      "limit": {
       "type": "integer",
       "description": "Max symbols to return in one call (default and hard cap 2000). Narrow with 'path' or page with 'offset' when truncated."
      }
     },
     "additionalProperties": false
    }

{
     "$schema": "https://json-schema.org/draft/2020-12/schema",
     "type": "object",
     "properties": {
      "filePath": {
       "type": "string",
       "description": "The absolute path to the file or directory to read"
      },
      "offset": {
       "minimum": 0,
       "type": "integer",
       "maximum": 9007199254740991,
       "description": "The line number to start reading from (1-indexed)"
      },
      "limit": {
       "minimum": 0,
       "type": "integer",
       "maximum": 9007199254740991,
       "description": "The maximum number of lines to read (defaults to 2000)"
      }
     },
     "required": [
      "filePath"
     ]
    }

{
     "$schema": "https://json-schema.org/draft/2020-12/schema",
     "type": "object",
     "properties": {
      "name": {
       "type": "string",
       "description": "The name of the skill from available_skills"
      }
     },
     "required": [
      "name"
     ]
    }

{
     "$schema": "https://json-schema.org/draft/2020-12/schema",
     "type": "object",
     "properties": {
      "description": {
       "type": "string",
       "description": "A short (3-5 words) description of the task"
      },
      "prompt": {
       "type": "string",
       "description": "The task for the agent to perform"
      },
      "subagent_type": {
       "type": "string",
       "description": "The type of specialized agent to use for this task"
      },
      "task_id": {
       "type": "string",
       "description": "This should only be set if you mean to resume a previous task (you can pass a prior task_id and the task will continue the same subagent session as before instead of creating a fresh one)"
      },
      "command": {
       "type": "string",
       "description": "The command that triggered this task"
      }
     },
     "required": [
      "description",
      "prompt",
      "subagent_type"
     ]
    }

{
     "$schema": "https://json-schema.org/draft/2020-12/schema",
     "type": "object",
     "properties": {
      "todos": {
       "type": "array",
       "items": {
        "type": "object",
        "properties": {
         "content": {
          "type": "string",
          "description": "Brief description of the task"
         },
         "status": {
          "type": "string",
          "description": "Current status of the task: pending, in_progress, completed, cancelled"
         },
         "priority": {
          "type": "string",
          "description": "Priority level of the task: high, medium, low"
         }
        },
        "required": [
         "content",
         "status",
         "priority"
        ]
       },
       "description": "The updated todo list"
      }
     },
     "required": [
      "todos"
     ]
    }

{
     "$schema": "https://json-schema.org/draft/2020-12/schema",
     "type": "object",
     "properties": {
      "url": {
       "type": "string",
       "description": "The URL to fetch content from"
      },
      "format": {
       "type": "string",
       "enum": [
        "text",
        "markdown",
        "html"
       ],
       "description": "The format to return the content in (text, markdown, or html). Defaults to markdown.",
       "default": "markdown"
      },
      "timeout": {
       "type": "number",
       "description": "Optional timeout in seconds (max 120)"
      }
     },
     "required": [
      "url"
     ]
    }

{
     "$schema": "https://json-schema.org/draft/2020-12/schema",
     "type": "object",
     "properties": {
      "content": {
       "type": "string",
       "description": "The content to write to the file"
      },
      "filePath": {
       "type": "string",
       "description": "The absolute path to the file to write (must be absolute, not relative)"
      }
     },
     "required": [
      "content",
      "filePath"
     ]
    }
